_md_to_html EXTENSION — the exact approach, replacing ui.py:2576-2592 (prototype executed, output quoted above; ~34 lines total, ~20 of them new). The whole function becomes an index-driven while loop, because a pipe table needs two-line lookahead:

  _INLINE_CODE = re.compile(r'`([^`]+)`')
  _BOLD        = re.compile(r'\*\*([^*]+)\*\*')

  def _cells(raw):      return [c.strip() for c in raw.strip().strip('|').split('|')]
  def _is_rule_row(cs): return bool(cs) and all(re.fullmatch(r':?-{2,}:?', c.strip()) for c in cs)

  def _inline(line):                      # ESCAPE FIRST, then reintroduce markup
      s = _esc(line)
      s = _INLINE_CODE.sub(r'<code>\1</code>', s)
      s = _BOLD.sub(r'<b>\1</b>', s)
      return s

  def _md_to_html(md):
      out, lines, i = [], md.splitlines(), 0
      while i < len(lines):
          raw, s = lines[i], lines[i].strip()
          if s.startswith('|') and i + 1 < len(lines) and _is_rule_row(_cells(lines[i + 1])):
              head = _cells(raw); i += 2; body = []
              while i < len(lines) and lines[i].strip().startswith('|'):
                  body.append(_cells(lines[i])); i += 1
              th = ''.join(f'<th>{_inline(c)}</th>' for c in head)
              tr = ''.join('<tr>' + ''.join(f'<td>{_inline(c)}</td>' for c in r) + '</tr>'
                           for r in body)
              out.append(f"<table class='rtab'><thead><tr>{th}</tr></thead><tbody>{tr}</tbody></table>")
              continue
          if   raw.startswith('### '): out.append(f"<div class='r-h3'>{_inline(raw[4:])}</div>")
          elif raw.startswith('## '):  out.append(f"<div class='r-h2'>{_inline(raw[3:])}</div>")
          elif raw.startswith('# '):   out.append(f"<div class='r-h1'>{_inline(raw[2:])}</div>")
          elif s.startswith('- '):     out.append(f"<div class='r-li'>&bull; {_inline(s[2:])}</div>")
          elif s == '---':             out.append("<hr class='r-hr'>")
          elif s == '':                out.append("<div style='height:.5rem'></div>")
          else:                        out.append(f'<div>{_inline(raw)}</div>')
          i += 1
      return ''.join(out)

Order matters: '### ' must be tested before '## ' and '# ', and the table branch before everything (a header row is otherwise an ordinary <div>). The ''.join emits zero whitespace between tags, which is what keeps a <table> safe inside the .report block's white-space:pre-wrap (ui.py:242-243).

